CREATE TABLE config (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL, json TEXT NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, day TEXT NOT NULL, action TEXT NOT NULL, revision INTEGER NOT NULL, target INTEGER NOT NULL, deadline INTEGER NOT NULL, source TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', detail TEXT, updated TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(day,action,revision));
CREATE INDEX jobs_day ON jobs(day,target);
CREATE TABLE attempts (ip TEXT PRIMARY KEY, count INTEGER NOT NULL, reset INTEGER NOT NULL);
